module coherence_readers_test_harness (
    input logic i_clk,
    input logic i_rst,
    input logic i_fatal_stop,
    input logic i_req_valid,
    output logic o_req_ready,
    input logic [31:0] i_req_addr,
    input logic [3:0] i_req_id,
    output logic o_resp_valid,
    output logic [3:0] o_resp_id,
    output logic [255:0] o_resp_data,
    output logic o_resp_error,
    input logic i_fence,
    input logic i_imem_done,
    output logic o_fence_done,
    input logic i_use_fetch,
    input logic i_fetch_valid,
    input logic i_fetch_prefetch,
    input logic [63:0] i_pc,
    input logic i_retarget,
    input logic i_invalidate,
    output logic o_instr_valid,
    output logic [63:0] o_instr,
    output logic [61:0] o_served_word,
    input logic i_walk_valid,
    output logic o_walk_ready,
    input logic [26:0] i_vpn,
    input logic [43:0] i_root,
    input logic i_discard,
    output logic o_walk_valid,
    output riscv_pkg::ptw_resp_t o_translation,
    output logic o_line_valid,
    output logic o_line_ready,
    output logic o_line_resp,
    output logic o_line_error,
    output logic o_if_accept,
    output logic [2:0] o_if_id,
    output logic o_if_response,
    output logic [2:0] o_if_response_id,
    output logic o_d_valid,
    input logic i_d_ready,
    output logic [343:0] o_d,
    input logic i_g_valid,
    output logic o_g_ready,
    input logic [306:0] i_g,
    output logic o_c_valid,
    input logic i_c_ready,
    output logic [49:0] o_c,
    input logic i_u_valid,
    output logic o_u_ready,
    input logic [46:0] i_u
);
  logic fetch_req;
  logic [31:0] fetch_addr, line_addr;
  logic [3:0] fetch_id;
  logic [2:0] line_id, line_resp_id;
  logic [255:0] line_data;
  assign o_if_accept = hart.if_req_valid && hart.if_req_ready;
  assign o_if_id = hart.if_req_id;
  assign o_if_response = hart.if_resp_valid;
  assign o_if_response_id = hart.if_resp_id;
  coherent_hart_cache #(
      .CACHE_BYTES(1024),
      .L1I_CACHE_BYTES(1024),
      .L1D_MISSES(1),
      .SIM_FAST_MAINT(1)
  ) hart (
      .i_clk(i_clk),
      .i_rst(i_rst),
      .i_fatal_stop(i_fatal_stop),
      .i_read_valid('0),
      .i_read_id('0),
      .i_read_kind('0),
      .i_read_size('0),
      .i_read_tag('0),
      .i_address('0),
      .o_read_valid(),
      .i_read_ready('0),
      .o_read_id(),
      .o_read_data(),
      .o_read_error(),
      .i_write_mask('0),
      .i_write_data('0),
      .i_write_atomic('0),
      .i_write_sc('0),
      .i_write_tag('0),
      .o_write_done(),
      .o_write_inflight(),
      .o_store_ready(),
      .o_pending_store(),
      .o_sc_write_pending(),
      .o_atomic_live(),
      .o_block_valid(),
      .o_block_addr(),
      .i_atomic_protected('0),
      .i_sc_valid('0),
      .o_sc_ready(),
      .i_sc_address('0),
      .i_sc_size('0),
      .i_sc_tag('0),
      .i_sc_commit('0),
      .o_sc_result_valid(),
      .i_sc_result_ready('0),
      .o_sc_success(),
      .o_sc_error(),
      .o_sc_write_done(),
      .o_sc_write_tag(),
      .i_reservation_valid('0),
      .i_reservation_addr('0),
      .i_reservation_size('0),
      .o_cut_hold(),
      .o_cut_admit_valid(),
      .i_cut_admit_ready('0),
      .i_cut_admit_clean('0),
      .o_cut_address(),
      .o_cut_inval_valid(),
      .i_cut_inval_done('0),
      .o_cut_release(),
      .o_d_valid(o_d_valid),
      .i_d_ready(i_d_ready),
      .o_d(o_d),
      .i_p_valid('0),
      .o_p_ready(),
      .i_p('0),
      .o_r_valid(),
      .i_r_ready('0),
      .o_r(),
      .o_w_valid(),
      .i_w_ready('0),
      .o_w(),
      .i_wa_valid('0),
      .o_wa_ready(),
      .i_wa('0),
      .i_g_valid(i_g_valid),
      .o_g_ready(o_g_ready),
      .i_g(i_g),
      .o_c_valid(o_c_valid),
      .i_c_ready(i_c_ready),
      .o_c(o_c),
      .i_u_valid(i_u_valid),
      .o_u_ready(o_u_ready),
      .i_u(i_u),
      .i_iup_req_valid(i_use_fetch ? fetch_req : i_req_valid),
      .o_iup_req_ready(o_req_ready),
      .i_iup_req_addr(i_use_fetch ? fetch_addr : i_req_addr),
      .i_iup_req_id(i_use_fetch ? fetch_id : i_req_id),
      .o_iup_resp_valid(o_resp_valid),
      .o_iup_resp_id(o_resp_id),
      .o_iup_resp_data(o_resp_data),
      .o_iup_resp_error(o_resp_error),
      .i_walk_req_valid(o_line_valid),
      .o_walk_req_ready(o_line_ready),
      .i_walk_req_addr(line_addr),
      .i_walk_req_id(line_id),
      .o_walk_resp_valid(o_line_resp),
      .o_walk_resp_id(line_resp_id),
      .o_walk_resp_data(line_data),
      .o_walk_resp_error(o_line_error),
      .i_fence_sync(i_fence),
      .i_imem_sync_done(i_imem_done),
      .o_fence_done(o_fence_done),
      .o_l1i_perf_events(),
      .o_l1d_perf_events(),
      .o_fatal(),
      .o_fatal_addr()
  );
  fetch_provider #(
      .ENABLE_RESPONSE_ERRORS(1),
      .LINE_ID_BITS(4)
  ) fetcher (
      .i_clk(i_clk),
      .i_rst(i_rst),
      .i_pc(i_pc),
      .i_pa0(i_pc[31:0]),
      .i_pa1(i_pc[31:0] + 32'd4),
      .i_pa_valid(i_fetch_valid),
      .i_fault0('0),
      .i_fault0_page('0),
      .i_fault1('0),
      .i_fault1_page('0),
      .i_line_after_ok(i_fetch_prefetch),
      .i_retarget(i_retarget),
      .i_fetch_replay_consume('0),
      .i_pipeline_stall(1'b0),
      .o_instr(o_instr),
      .o_instr_sideband(),
      .o_pc_metadata_by_parity(),
      .o_pc_pairability_by_parity(),
      .o_slot2_start_valid_lo_by_parity(),
      .o_instr_bank_sel_r(),
      .o_served_word(o_served_word),
      .o_served_last_word(),
      .o_served_prev_word(),
      .o_served_prev_word_valid(),
      .o_served_fault0(),
      .o_served_fault0_page(),
      .o_served_fault1(),
      .o_served_fault1_page(),
      .o_instr_valid(o_instr_valid),
      .o_instr_valid_next(),
      .i_l1i_miss_outstanding('0),
      .o_perf_miss_stall(),
      .o_line_req_valid(fetch_req),
      .i_line_req_ready(o_req_ready && i_use_fetch),
      .o_line_req_write(),
      .o_line_req_addr(fetch_addr),
      .o_line_req_wdata(),
      .o_line_req_wstrb(),
      .o_line_req_id(fetch_id),
      .i_line_resp_valid(o_resp_valid && i_use_fetch),
      .i_line_resp_error(o_resp_error),
      .i_line_resp_id(o_resp_id),
      .i_line_resp_rdata(o_resp_data),
      .i_invalidate(i_invalidate)
  );
  ptw #(
      .ENABLE_RESPONSE_ERRORS(1),
      .WALK_ID_BITS(3)
  ) walker (
      .i_clk(i_clk),
      .i_rst(i_rst),
      .i_root_ppn(i_root),
      .i_req_valid(i_walk_valid),
      .o_req_ready(o_walk_ready),
      .i_req_vpn(i_vpn),
      .i_discard(i_discard),
      .o_busy(),
      .o_resp_valid(o_walk_valid),
      .o_resp(o_translation),
      .o_line_req_valid(o_line_valid),
      .i_line_req_ready(o_line_ready),
      .o_line_req_addr(line_addr),
      .o_line_req_id(line_id),
      .i_line_resp_valid(o_line_resp),
      .i_line_resp_error(o_line_error),
      .i_line_resp_id(line_resp_id),
      .i_line_resp_rdata(line_data)
  );
endmodule
